const entrada = $input.first().json;

// Extraer datos con valores por defecto seguros
const telefono = String(entrada.telefono || '').replace(/[^0-9]/g, '');
const nombre = (entrada.nombre || '').trim() || `Prospecto WhatsApp ${telefono}`;
const servicio = (entrada.servicio || 'Seguridad Electrónica').trim();
const direccion = (entrada.direccion || 'Lima, Perú').trim();
const derivar = Boolean(entrada.derivar);
const estado = entrada.estado || (derivar ? 'Atención Urgente' : 'No Contactado');

// Si la IA derivó a humano o no hay respuesta, mensaje de respaldo
const mensajeRespuesta = derivar || !entrada.respuesta
  ? 'Gracias por comunicarte con Atrios. Un asesor comercial especializado se pondrá en contacto contigo a la brevedad para brindarte una atención personalizada.'
  : entrada.respuesta;

return [{
  json: {
    telefono,
    nombre,
    servicio,
    direccion,
    estado,
    derivar,
    mensaje_final: mensajeRespuesta,
    Last_Name: nombre,
    Company: 'Particular - Atrios [TEST]',
    Phone: telefono,
    Street: direccion,
    Lead_Status: estado,
    Description: `Servicio de interés: ${servicio} | Origen: WhatsApp Bot Atrios | Derivar a Humano: ${derivar ? 'SÍ' : 'NO'}`
  }
}];

const respuestaZoho = $input.first().json;
const datosLead = $('Preparar Datos Lead').first().json;

const errorLog = {
  nivel: 'WARN',
  tipo: 'ERROR_VALIDACION_ZOHO',
  fecha: new Date().toISOString(),
  telefono: datosLead.telefono,
  nombre: datosLead.nombre,
  detalle: respuestaZoho.error || respuestaZoho.message || respuestaZoho.data?.[0]?.message || 'Fallo de validación de campos en Zoho CRM',
  codigo: respuestaZoho.code || respuestaZoho.data?.[0]?.code || 'VALIDATION_FAILED'
};

console.warn('⚠️ [AUDITORIA ATRIOS] Error al insertar en Zoho CRM:', JSON.stringify(errorLog));

// Pasar datos originales hacia WhatsApp para no cortar la experiencia del usuario
return [{
  json: {
    ...datosLead,
    zoho_log: errorLog
  }
}];

